import{_ as i,a0 as l,w as c,s,ao as p,I as r,x as o,a1 as t,A as a}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const k=JSON.parse('{"title":"Nmcli 网络管理命令行工具基础 | LCTT x X-CMD","titleTemplate":false,"description":"Nmcli 网络管理命令行工具基础 | LCTT (201509) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Nmcli 网络管理命令行工具基础 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Nmcli 网络管理命令行工具基础 | LCTT (201509) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201509/20150824 Basics Of NetworkManager Command Line Tool Nmcli","title":"Nmcli 网络管理命令行工具基础","tag":"201509","desc":""},"relativePath":"201509/20150824 Basics Of NetworkManager Command Line Tool Nmcli.md","filePath":"[post].md"}'),d={name:"201509/20150824 Basics Of NetworkManager Command Line Tool Nmcli.md"};function m(h,e,f,g,u,w){const n=l("Link");return c(),s("div",null,[e[11]||(e[11]=p(`<h1 id="nmcli-网络管理命令行工具基础" tabindex="-1">Nmcli 网络管理命令行工具基础 <a class="header-anchor" href="#nmcli-网络管理命令行工具基础" aria-label="Permalink to “Nmcli 网络管理命令行工具基础”">​</a></h1><p><img src="http://1102047360.rsc.cdn77.org/wp-content/uploads/2015/08/networking1.jpg" alt=""></p><h3 id="介绍" tabindex="-1">介绍 <a class="header-anchor" href="#介绍" aria-label="Permalink to “介绍”">​</a></h3><p>在本教程中，我们会在CentOS / RHEL 7中讨论网络管理工具（NetworkManager command line tool），也叫<strong>nmcli</strong>。那些使用<strong>ifconfig</strong>的用户应该在CentOS 7中避免使用<strong>ifconfig</strong> 了。</p><p>让我们用nmcli工具配置一些网络设置。</p><h4 id="要得到系统中所有接口的地址信息" tabindex="-1">要得到系统中所有接口的地址信息 <a class="header-anchor" href="#要得到系统中所有接口的地址信息" aria-label="Permalink to “要得到系统中所有接口的地址信息”">​</a></h4><pre><code>[root@localhost ~]# ip addr show
</code></pre><p><strong>示例输出：</strong></p><pre><code>1: lo: &lt;LOOPBACK,UP,LOWER_UP&gt; mtu 65536 qdisc noqueue state UNKNOWN 
 link/loopback 00:00:00:00:00:00 brd 00:00:00:00:00:00
 inet 127.0.0.1/8 scope host lo
 valid_lft forever preferred_lft forever
 inet6 ::1/128 scope host 
 valid_lft forever preferred_lft forever
2: eno16777736: &lt;BROADCAST,MULTICAST,UP,LOWER_UP&gt; mtu 1500 qdisc pfifo_fast state UP qlen 1000
 link/ether 00:0c:29:67:2f:4c brd ff:ff:ff:ff:ff:ff
 inet 192.168.1.51/24 brd 192.168.1.255 scope global eno16777736
 valid_lft forever preferred_lft forever
 inet6 fe80::20c:29ff:fe67:2f4c/64 scope link 
 valid_lft forever preferred_lft forever
</code></pre><h4 id="检索与已连接的接口相关的数据包统计" tabindex="-1">检索与已连接的接口相关的数据包统计 <a class="header-anchor" href="#检索与已连接的接口相关的数据包统计" aria-label="Permalink to “检索与已连接的接口相关的数据包统计”">​</a></h4><pre><code>[root@localhost ~]# ip -s link show eno16777736
</code></pre><p><strong>示例输出：</strong></p><p><img src="http://www.unixmen.com/wp-content/uploads/2015/08/unxmen_0111.png" alt=""></p><h4 id="得到路由配置" tabindex="-1">得到路由配置 <a class="header-anchor" href="#得到路由配置" aria-label="Permalink to “得到路由配置”">​</a></h4><pre><code>[root@localhost ~]# ip route
</code></pre><p>示例输出：</p><pre><code>default via 192.168.1.1 dev eno16777736 proto static metric 100 
192.168.1.0/24 dev eno16777736 proto kernel scope link src 192.168.1.51 metric 100
</code></pre><h4 id="分析主机-网站路径" tabindex="-1">分析主机/网站路径 <a class="header-anchor" href="#分析主机-网站路径" aria-label="Permalink to “分析主机/网站路径”">​</a></h4><pre><code>[root@localhost ~]# tracepath unixmen.com
</code></pre><p>输出像traceroute，但是更加完整。</p><p><img src="http://www.unixmen.com/wp-content/uploads/2015/08/unxmen_01211.png" alt=""></p><h3 id="nmcli-工具" tabindex="-1">nmcli 工具 <a class="header-anchor" href="#nmcli-工具" aria-label="Permalink to “nmcli 工具”">​</a></h3><p><strong>nmcli</strong> 是一个非常丰富和灵活的命令行工具。nmcli使用的情况有：</p><ul><li><strong>设备</strong> – 正在使用的网络接口</li><li><strong>连接</strong> – 一组配置设置，对于一个单一的设备可以有多个连接，可以在连接之间切换。</li></ul><h4 id="找出有多少连接服务于多少设备" tabindex="-1">找出有多少连接服务于多少设备 <a class="header-anchor" href="#找出有多少连接服务于多少设备" aria-label="Permalink to “找出有多少连接服务于多少设备”">​</a></h4><pre><code>[root@localhost ~]# nmcli connection show
</code></pre><p><img src="http://www.unixmen.com/wp-content/uploads/2015/08/unxmen_013.png" alt=""></p><h4 id="得到特定连接的详情" tabindex="-1">得到特定连接的详情 <a class="header-anchor" href="#得到特定连接的详情" aria-label="Permalink to “得到特定连接的详情”">​</a></h4><pre><code>[root@localhost ~]# nmcli connection show eno1
</code></pre><p><strong>示例输出：</strong></p><p><img src="http://www.unixmen.com/wp-content/uploads/2015/08/unxmen_0141.png" alt=""></p><h4 id="得到网络设备状态" tabindex="-1">得到网络设备状态 <a class="header-anchor" href="#得到网络设备状态" aria-label="Permalink to “得到网络设备状态”">​</a></h4><pre><code>[root@localhost ~]# nmcli device status
</code></pre><hr><pre><code> DEVICE               TYPE              STATE          CONNECTION 
eno16777736            ethernet      connected              eno1 
lo                     loopback      unmanaged               --
</code></pre><h4 id="使用-dhcp-创建新的连接" tabindex="-1">使用“dhcp”创建新的连接 <a class="header-anchor" href="#使用-dhcp-创建新的连接" aria-label="Permalink to “使用“dhcp”创建新的连接”">​</a></h4><pre><code>[root@localhost ~]# nmcli connection add con-name &quot;dhcp&quot; type ethernet ifname eno16777736
</code></pre><p>这里，</p><ul><li><strong>connection add</strong> – 添加新的连接</li><li><strong>con-name</strong> – 连接名</li><li><strong>type</strong> – 设备类型</li><li><strong>ifname</strong> – 接口名</li></ul><p>这个命令会使用dhcp协议添加连接</p><p><strong>示例输出：</strong></p><pre><code>Connection &#39;dhcp&#39; (163a6822-cd50-4d23-bb42-8b774aeab9cb) successfully added.
</code></pre><h4 id="不通过dhcp分配ip-使用-static-添加地址" tabindex="-1">不通过dhcp分配IP，使用“static”添加地址 <a class="header-anchor" href="#不通过dhcp分配ip-使用-static-添加地址" aria-label="Permalink to “不通过dhcp分配IP，使用“static”添加地址”">​</a></h4><pre><code>[root@localhost ~]# nmcli connection add con-name &quot;static&quot; ifname eno16777736 autoconnect no type ethernet ip4 192.168.1.240 gw4 192.168.1.1
</code></pre><p><strong>示例输出：</strong></p><pre><code>Connection &#39;static&#39; (8e69d847-03d7-47c7-8623-bb112f5cc842) successfully added.
</code></pre><p><strong>更新连接：</strong></p><pre><code>[root@localhost ~]# nmcli connection up eno1
</code></pre><p>再检查一遍，ip地址是否已经改变</p><pre><code>[root@localhost ~]# ip addr show
</code></pre><p><img src="http://www.unixmen.com/wp-content/uploads/2015/08/unxmen_0151.png" alt=""></p><h4 id="添加dns设置到静态连接中" tabindex="-1">添加DNS设置到静态连接中 <a class="header-anchor" href="#添加dns设置到静态连接中" aria-label="Permalink to “添加DNS设置到静态连接中”">​</a></h4><pre><code>[root@localhost ~]# nmcli connection modify &quot;static&quot; ipv4.dns 202.131.124.4
</code></pre><h4 id="添加更多的dns" tabindex="-1">添加更多的DNS <a class="header-anchor" href="#添加更多的dns" aria-label="Permalink to “添加更多的DNS”">​</a></h4><pre><code>[root@localhost ~]# nmcli connection modify &quot;static&quot; +ipv4.dns 8.8.8.8
</code></pre><p><strong>注意</strong>：要使用额外的<strong>+</strong>符号，并且要是<strong>+ipv4.dns</strong>，而不是<strong>ip4.dns</strong>。</p><p>####添加一个额外的ip地址####</p><pre><code>[root@localhost ~]# nmcli connection modify &quot;static&quot; +ipv4.addresses 192.168.200.1/24
</code></pre><p>使用命令刷新设置：</p><pre><code>[root@localhost ~]# nmcli connection up eno1
</code></pre><p><img src="http://www.unixmen.com/wp-content/uploads/2015/08/unxmen_016.png" alt=""></p><p>你会看见，设置生效了。</p><p>完结。</p><hr>`,64)),r("p",null,[e[1]||(e[1]=o("via: ",-1)),t(n,{href:"http://www.unixmen.com/basics-networkmanager-command-line-tool-nmcli/"},{default:a(()=>[...e[0]||(e[0]=[o("http://www.unixmen.com/basics-networkmanager-command-line-tool-nmcli/",-1)])]),_:1})]),r("p",null,[e[4]||(e[4]=o("作者：Rajneesh Upadhyay 译者：",-1)),t(n,{href:"https://github.com/geekpi"},{default:a(()=>[...e[2]||(e[2]=[o("geekpi",-1)])]),_:1}),e[5]||(e[5]=o(" 校对：",-1)),t(n,{href:"https://github.com/wxy"},{default:a(()=>[...e[3]||(e[3]=[o("wxy",-1)])]),_:1})]),r("p",null,[e[8]||(e[8]=o("本文由 ",-1)),t(n,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...e[6]||(e[6]=[o("LCTT",-1)])]),_:1}),e[9]||(e[9]=o(" 原创翻译，",-1)),t(n,{href:"https://linux.cn/"},{default:a(()=>[...e[7]||(e[7]=[o("Linux中国",-1)])]),_:1}),e[10]||(e[10]=o(" 荣誉推出",-1))])])}const T=i(d,[["render",m]]);export{k as __pageData,T as default};
